class MedicineSyntheticPolicy extends MedicineGovernancePolicy {
    // Legacy synthetic fixture only; production binding is exercised by Phase 3.22 tests.
    public function requireQualificationBinding(MedicineGovernanceRepository $repository,array $grant,string $scope):array {$this->requireQualification($grant,$scope);return [];}
    public function owner(int $actor):bool {return $actor===8;}
    public function requireEvidenceFor(array $evidence,string $scope,string $id,string $snapshotHash):void {$this->requireEvidence($evidence,$scope);}
    public function requireSubmission(?array $event,int $revision):void {}
    public function governedPilotRequired():bool {return false;}
    public function requireAdministrator(int $actor):void {if($actor!==8){throw new MedicinePersistenceException('Synthetic administration denied.',403);}}
    public function requireQualification(array $grant,string $scope):void {if(!str_starts_with($grant['qualification_reference']??'','SYNTHETIC')||!in_array($grant['qualification_scope']??null,[$scope,'catalog'],true)||empty($grant['qualification_assessed_by'])){throw new MedicinePersistenceException('Synthetic qualification denied.',403);}}
    public function requireEvidence(array $evidence,string $scope):void {if(($evidence['kind']??null)!=='identity'||($evidence['issuer']??null)!=='SYNTHETIC_TEST_ONLY'){throw new MedicinePersistenceException('Synthetic evidence denied.',403);}}
}
class MedicineGovernanceMemory extends MedicineGovernanceRepository {
    public array $grantRows=[],$eventRows=[],$assessmentRows=[],$lifecycleRows=[];public bool $fault=false;
    public function __construct(public MedicineMemoryRepository $inner) {}
    public function transaction(callable $action):mixed {$snapshot=serialize([$this->grantRows,$this->eventRows,$this->assessmentRows,$this->inner->data]);try{return $action();}catch(Throwable $e){[$this->grantRows,$this->eventRows,$this->assessmentRows,$this->inner->data]=unserialize($snapshot);throw $e;}}
    public function actor(int $id,bool $lock=false):?array {return $id>=1&&$id<=8?['id'=>$id,'status'=>$id===7?'inactive':'active']:null;}
    public function grants(int $actor,string $capability,string $scope,bool $lock=true):array {return array_values(array_filter($this->grantRows,fn($r)=>(int)$r['user_id']===$actor&&$r['capability']===$capability&&in_array($r['scope'],[$scope,'catalog'],true)));}
    public function grant(string $id,bool $lock=true):?array {return $this->grantRows[$id]??null;}
    public function insertGrant(array $r):string {$id=(string)(count($this->grantRows)+1);$this->grantRows[$id]=$r+['id'=>$id,'revoked_by'=>null,'revoked_at'=>null,'revocation_reason'=>null];return $id;}
    public function revokeGrant(string $id,int $actor,string $now,string $reason):void {$this->grantRows[$id]=array_replace($this->grantRows[$id],['is_active'=>0,'revoked_by'=>$actor,'revoked_at'=>$now,'revocation_reason'=>$reason]);}
    public function target(string $kind,string $id,bool $lock=true):?array {return $this->inner->data[['chemical'=>'refs','composition'=>'identities','presentation'=>'presentations'][$kind]??'invalid'][$id]??null;}
    public function changeTarget(string $kind,string $id,array $r):void {$table=['chemical'=>'refs','composition'=>'identities','presentation'=>'presentations'][$kind];$this->inner->data[$table][$id]=array_replace($this->inner->data[$table][$id],$r);}
    public function registry(string $tag,string $id):?array {return $this->inner->data[$tag==='S'?'substances':'forms'][$id]??null;}
    public function registryLifecycle(string $tag,string $id):string {return (string)($this->lifecycleRows[$tag.':'.$id]['id']??'0');}
    public function registryActivity(string $tag,string $id,int $active):void {$table=$tag==='S'?'substances':'forms';$old=$this->inner->data[$table][$id]['is_active'];if($old!==$active){$this->inner->data[$table][$id]['is_active']=$active;$this->lifecycleRows[$tag.':'.$id]=['id'=>1+(int)($this->lifecycleRows[$tag.':'.$id]['id']??0),'old_active'=>$old,'new_active'=>$active,'source'=>'registry_trigger'];}}
    public function ingredients(string $id,bool $lock=false):array {return $this->inner->ingredients($id,$lock);}
    public function strengths(string $id,bool $lock=false):array {return $this->inner->strengths($id,$lock);}
    public function assessment(string $id):?array {return $this->assessmentRows[$id]??null;}
    public function saveAssessment(array $r,bool $exists):void {$this->assessmentRows[$r['chemical_ref_id']]=$r;}
    public function events(string $kind,string $id):array {return array_values(array_filter($this->eventRows,fn($r)=>$r['scope']===$kind&&$r['subject']===$id));}
    public function latest(string $kind,string $id):?array {$r=$this->events($kind,$id);return $r?end($r):null;}
    public function event(string $id):?array {return $this->eventRows[$id]??null;}
    public function appendEvent(string $kind,string $id,array $r):string {$event=(string)(count($this->eventRows)+1);$this->eventRows[$event]=['id'=>$event,'scope'=>$kind,'subject'=>$id]+$r;if($this->fault){throw new PDOException('PRIVATE_AUDIT_FAILURE');}return $event;}
}
function medicineGovernanceObjects(MedicineGovernanceRepository $repo,?MedicineGovernancePolicy $policy=null):array {
    $policy??=new MedicineSyntheticPolicy();$rules=new App\Services\MedicineCanonicalizer();$auth=new MedicineTestAuth(1);$elig=new MedicineEligibilityService($repo,$rules,$policy);$authority=new MedicineAuthorizationService($repo,$policy,$elig);$service=new MedicineGovernanceService($repo,$authority,$elig,$policy,$rules,$auth);return [$service,$auth,$authority,$elig,$policy];
}
function medicineGovernanceFixture():array {
    [$inner,$legacy]=medicineFixture();$medicine=$legacy->createMedicine(['ingredients'=>[['substance_id'=>'2'],['substance_id'=>'10']],'presentation'=>medicinePresentation()]);foreach($inner->data['refs'] as &$row){$row+=['created_by'=>1];}unset($row);
    $repo=new MedicineGovernanceMemory($inner);foreach([[1,'contributor'],[2,'reviewer'],[3,'editor'],[4,'steward'],[5,'publisher']] as [$actor,$cap]){$repo->insertGrant(['user_id'=>$actor,'capability'=>$cap,'scope'=>'catalog','is_active'=>1,'qualification_reference'=>$cap==='reviewer'?'SYNTHETIC qualification':null,'qualification_assessed_by'=>$cap==='reviewer'?8:null,'qualification_scope'=>$cap==='reviewer'?'catalog':null,'granted_by'=>8,'granted_at'=>'2020-01-01 00:00:00.000001','expires_at'=>'2030-01-01 00:00:00.000001']);}
    return [$repo,...medicineGovernanceObjects($repo),$medicine];
}
function medicineGovernanceInput(MedicineGovernanceRepository $repo,MedicineEligibilityService $elig,string $scope,string $id,array $extra=[]):array {$row=$repo->target($scope,$id);return ['expected_revision'=>$row['metadata_revision'],'expected_snapshot_hash'=>hash('sha256',$elig->json($elig->snapshot($scope,$id)))]+$extra;}
function medicineSyntheticEvidence():array {return ['kind'=>'identity','issuer'=>'SYNTHETIC_TEST_ONLY','record'=>'Synthetic reference','version'=>'1','locator'=>'Synthetic page 1','source_sha256'=>str_repeat('a',64)];}
